function adb(cmd, timeout = 10000) {
  try {
    return execSync(`adb -s ${ADB_DEVICE} ${cmd}`, {
      timeout,
      encoding: "utf8",
      stdio: ["pipe", "pipe", "pipe"],
    }).trim();
  } catch (err) {
    return err.stdout ? err.stdout.trim() : "";
  }
}

function shell(cmd, timeout = 10000) {
  return adb(`shell "${cmd.replace(/"/g, '\\"')}"`, timeout);
}

